<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, shallowRef, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { CheckCircle2, Download, FileCheck2, FileSpreadsheet, FolderCog, Play, UploadCloud } from 'lucide-vue-next'
import { api } from '../api'
import type { CatalogImportRun } from '../types'

const items=ref<CatalogImportRun[]>([]),file=ref<File>(),bundleFile=ref<File>(),loading=ref(false),bundleLoading=ref(false),podLoading=ref('')
const ozonStores=ref<any[]>([]),categoryOptions=shallowRef<any[]>([]),categoryStoreId=ref(''),selectedCategoryKey=ref(''),categoryLoading=ref(false),categoryMeta=shallowRef<any>()
const categorySelectOptions=computed(()=>categoryOptions.value.map(item=>({value:`${item.description_category_id}:${item.type_id}`,label:item.display})))
let categoryRequest=0
const pipelineOpen=ref(false),pipelineLoading=ref(false),connections=ref<any[]>([]),pipelineJob=ref<any>()
const stepOptions=[['generate_images','AI 批量生图','从本地产品图生成主图和附图'],['generate_copywriting','文案生成','输出 Ozon 文案 Excel'],['watermark','批量加水印','生成独立水印图目录'],['upload_original','上传原图','上传 OSS 并输出链接表'],['upload_watermarked','上传水印图','上传 OSS 并输出链接表']]
const allSteps=stepOptions.map(x=>x[0])
const pipelineStorageKey='erp:self-listing:pipeline-config:v1'
const defaultPipeline=()=>({selected_steps:[...allSteps],product_root:'',output_dir:'',watermark_root:'',watermark_filename:'水印.png',source_subfolder:'_generated',watermark_position:'bottom-right',watermark_scale:0.2,watermark_opacity:0.7,original_oss_prefix:'OZON/original',watermarked_oss_prefix:'OZON/watermarked',product_hint:'',category_hint:'',page_keywords:'',image_plan_count:8,repair_only_missing:false,ai_chat_connection_id:'',ai_image_connection_id:'',oss_connection_id:'',oss_dry_run:false})
function loadSavedPipeline(){try{const saved=JSON.parse(localStorage.getItem(pipelineStorageKey)||'{}');return {...defaultPipeline(),...saved,repair_only_missing:false}}catch{return defaultPipeline()}}
const pipeline=ref<any>(loadSavedPipeline())
const route=useRoute(),mode=String(route.meta.importMode||'')
const inputFields=['来源链接','中文名称','SKU','规格型号','颜色','尺码','材质','拿货价','长','宽','高','长(cm)','宽(cm)','高(cm)','重量(g)','备注']
const generatedFields=['主图链接','附图链接','商品名称 / 产品名称']
const visibleItems=computed(()=>mode==='self_selected'?items.value.filter(x=>x.kind==='self_selected'||x.kind==='self_selected_bundle'):items.value)
async function load(){items.value=(await api.get<any>('/catalog/imports')).items}
async function pod(dryRun:boolean){if(!dryRun)await ElMessageBox.confirm('将原地索引指纹科技图片合成的全部历史产品、SKU、OSS 资产和生产资料。原数据库与图片不会修改。','执行 POD 全量迁移',{type:'warning'});podLoading.value=dryRun?'dry':'run';try{const result=await api.post<any>('/catalog/imports/pod',{dry_run:dryRun});ElMessage.success(dryRun?'POD 预演任务已创建':'POD 全量迁移任务已创建');window.location.hash='';await load()}finally{podLoading.value=''}}
function selectedCategory(){return categoryOptions.value.find(x=>`${x.description_category_id}:${x.type_id}`===selectedCategoryKey.value)}
function appendCategory(form:FormData){const category=selectedCategory();if(!category)throw new Error('请先选择 Ozon 类目');form.append('store_id',categoryStoreId.value);form.append('description_category_id',String(category.description_category_id));form.append('type_id',String(category.type_id))}
async function upload(dryRun:boolean){if(!file.value)return ElMessage.warning('请先选择产品信息表');if(!selectedCategory())return ElMessage.warning('请先选择本批产品的 Ozon 类目');loading.value=true;try{const form=new FormData();form.append('file',file.value);form.append('dry_run',String(dryRun));appendCategory(form);await api.upload('/catalog/imports/self-selected',form);ElMessage.success(dryRun?'校验任务已创建':'导入任务已创建');await load()}finally{loading.value=false}}
async function uploadBundle(dryRun:boolean){if(!bundleFile.value)return ElMessage.warning('请先选择产品资料包');if(!selectedCategory())return ElMessage.warning('请先选择本批产品的 Ozon 类目');bundleLoading.value=true;try{const form=new FormData();form.append('file',bundleFile.value);form.append('dry_run',String(dryRun));appendCategory(form);await api.upload('/catalog/imports/self-selected/bundle',form);ElMessage.success(dryRun?'资料包校验任务已创建':'产品与图片同步任务已创建');await load()}finally{bundleLoading.value=false}}
async function loadCategoryOptions(){const request=++categoryRequest,storeId=categoryStoreId.value;categoryOptions.value=[];selectedCategoryKey.value='';categoryMeta.value=undefined;categoryLoading.value=!!storeId;if(!storeId)return;try{const result=await api.get<any>(`/stores/${storeId}/category-options`);if(request!==categoryRequest||storeId!==categoryStoreId.value)return;categoryOptions.value=result.options||result.items||[];categoryMeta.value=result}catch(error:any){if(request===categoryRequest&&!String(error?.message||'').includes('还没有'))ElMessage.error(error?.message||'读取本地类目失败')}finally{if(request===categoryRequest)categoryLoading.value=false}}
async function syncCategories(){if(!categoryStoreId.value)return ElMessage.warning('请先选择 Ozon 店铺');const request=++categoryRequest,storeId=categoryStoreId.value;categoryLoading.value=true;try{const result=await api.post<any>(`/stores/${storeId}/categories/sync?language=ZH_HANS`,{});if(request!==categoryRequest||storeId!==categoryStoreId.value)return;categoryOptions.value=result.options||[];categoryMeta.value=result;selectedCategoryKey.value='';ElMessage.success(`已同步 ${result.option_count||categoryOptions.value.length} 个可选类目`)}finally{if(request===categoryRequest)categoryLoading.value=false}}
async function loadStores(){ozonStores.value=(await api.get<any>('/stores')).items.filter((x:any)=>x.platform==='ozon'&&x.enabled);if(!categoryStoreId.value&&ozonStores.value.length)categoryStoreId.value=ozonStores.value[0].id;await loadCategoryOptions()}
async function loadConnections(){connections.value=(await api.get<any>('/connections')).items;for(const type of ['ai_chat','ai_image','oss']){const field=`${type}_connection_id`;const current=connections.value.find(x=>x.id===pipeline.value[field]&&x.provider===type&&x.enabled);const fallback=connections.value.find(x=>x.provider===type&&x.enabled);if(!current)pipeline.value[field]=fallback?.id||''}}
async function openPipeline(){await loadConnections();document.getElementById('self-listing-pipeline')?.scrollIntoView({behavior:'smooth',block:'start'})}
async function chooseDirectory(field:'product_root'|'output_dir'|'watermark_root',title:string){
  const request={title,initial_dir:pipeline.value[field]||''}
  try{
    let result:any
    try{
      const controller=new AbortController()
      const timeout=setTimeout(()=>controller.abort(),2500)
      try{
        const probe=await fetch('http://127.0.0.1:48739/status',{mode:'cors',credentials:'omit',signal:controller.signal})
        if(!probe.ok || !(await probe.json()).ready)throw new Error('本机文件夹选择器未就绪')
      }finally{clearTimeout(timeout)}
      const response=await fetch('http://127.0.0.1:48739/select-directory',{method:'POST',mode:'cors',credentials:'omit',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)})
      result=await response.json()
      if(!response.ok)throw new Error(result.message||'本机文件夹选择器未响应')
    }catch(error){
      if(!(error instanceof TypeError) && !(error instanceof DOMException && error.name==='AbortError'))throw error
      // The original local ERP still owns its picker when no desktop client runs.
      result=await api.post<any>('/catalog/self-listing/select-directory',request)
    }
    if(!result.cancelled)pipeline.value[field]=result.path
  }catch(error:any){ElMessage.error(String(error?.message||'无法打开文件夹选择器').includes('只能在本地 ERP')?'请在当前电脑启动 ERP 执行端，或手动填写本机完整目录':error?.message||'无法打开文件夹选择器，请手动填写路径')}
}
function selectAllSteps(){pipeline.value.selected_steps=[...allSteps]}
function resetPipeline(){pipeline.value=defaultPipeline();localStorage.removeItem(pipelineStorageKey);void loadConnections();ElMessage.success('已恢复自主上架默认配置')}
async function startPipeline(repairOnly=false){const request={...pipeline.value};if(repairOnly){request.selected_steps=['generate_images'];request.repair_only_missing=true}else request.repair_only_missing=false;if(!request.selected_steps.length)return ElMessage.warning('请至少选择一个处理步骤');if(!request.product_root)return ElMessage.warning('请填写本地产品图片根目录');pipelineLoading.value=true;try{pipelineJob.value=await api.post<any>('/catalog/self-listing/pipeline',request);pipelineOpen.value=false;ElMessage.success(repairOnly?'已创建补跑任务，只生成缺失或损坏的图片':`已创建 ${request.selected_steps.length} 个步骤的处理任务`)}finally{pipelineLoading.value=false}}
function values(value:Record<string,number>){return Object.entries(value||{}).map(([key,count])=>`${key}: ${count}`).join(' · ')||'-'}
function statusText(value:string){return ({queued:'等待处理',running:'处理中',completed:'已完成',completed_with_errors:'部分完成',validation_failed:'校验未通过',failed:'失败'} as Record<string,string>)[value]||value}
function statusType(value:string){if(value==='completed')return 'success';if(value==='completed_with_errors'||value==='validation_failed')return 'warning';if(value==='failed')return 'danger';return 'info'}
watch(pipeline,value=>{const saved={...value,repair_only_missing:false};localStorage.setItem(pipelineStorageKey,JSON.stringify(saved))},{deep:true})
onMounted(()=>{load();loadConnections();if(mode==='self_selected')loadStores()})
onUnmounted(()=>{categoryRequest++})
</script>
<template><div class="page-stack">
  <template v-if="mode==='self_selected'">
    <section class="self-hero">
      <div><span class="hero-kicker">批量自主上架</span><h2>完整模板下载，本地处理后回传入库</h2><p>图片留在本地处理，ERP 只接收最终 Excel。列顺序和表头所在行都可以调整。</p></div>
      <div class="hero-actions"><a class="download-button" href="/ozon-self-listing-standard-template.xlsx?v=20260919-notes" download="ozon自主上架标准模板.xlsx"><Download :size="19"/><span><b>下载完整标准模板</b><small>包含全部 5 个工作表</small></span></a><button class="pipeline-button" @click="openPipeline"><Play :size="18"/><span><b>启动本地流水线</b><small>生图、文案、水印、OSS</small></span></button></div>
    </section>
    <section class="workflow-strip">
      <article><i>1</i><FileSpreadsheet :size="22"/><div><b>填写完整模板</b><span>整理产品和 SKU 基础资料</span></div></article>
      <article><i>2</i><FolderCog :size="22"/><div><b>本地程序处理</b><span>生图、文案、水印、OSS</span></div></article>
      <article><i>3</i><FileCheck2 :size="22"/><div><b>回填原模板</b><span>生成链接与商品名称</span></div></article>
      <article><i>4</i><UploadCloud :size="22"/><div><b>回传 ERP</b><span>校验并进入自主产品库</span></div></article>
    </section>
    <section id="self-listing-pipeline" class="panel pipeline-config-panel">
      <div class="panel-head"><div><h2>自主上架处理中心</h2><p>配置自动保存在当前电脑，刷新页面不会丢失</p></div><div><el-button link @click="resetPipeline">恢复默认</el-button><el-button link type="primary" @click="selectAllSteps">全选步骤</el-button></div></div>
      <div class="panel-body pipeline-layout">
        <div><h3 class="config-title">1. 选择处理步骤</h3><el-checkbox-group v-model="pipeline.selected_steps" class="step-picker"><el-checkbox v-for="step in stepOptions" :key="step[0]" :value="step[0]" border><b>{{step[1]}}</b><small>{{step[2]}}</small></el-checkbox></el-checkbox-group></div>
        <div><h3 class="config-title">2. 本地目录</h3><el-form label-width="125px" class="pipeline-form directory-form">
          <el-form-item label="产品图片根目录"><el-input v-model="pipeline.product_root" placeholder="选择或手动填写本地目录"/><el-button @click="chooseDirectory('product_root','选择产品图片根目录')">选择文件夹</el-button></el-form-item>
          <el-form-item label="输出表格目录"><el-input v-model="pipeline.output_dir" placeholder="留空自动创建"/><el-button @click="chooseDirectory('output_dir','选择输出表格目录')">选择文件夹</el-button></el-form-item>
          <el-form-item label="水印图目录"><el-input v-model="pipeline.watermark_root" placeholder="留空自动创建"/><el-button @click="chooseDirectory('watermark_root','选择水印图目录')">选择文件夹</el-button></el-form-item>
        </el-form></div>
        <div><h3 class="config-title">3. 生图、文案与水印配置</h3><el-form label-width="125px" class="pipeline-form">
          <el-form-item label="生图数量 / 提示"><el-input-number v-model="pipeline.image_plan_count" :min="1" :max="12"/><el-input v-model="pipeline.product_hint" placeholder="产品提示，可留空自动识别"/></el-form-item>
          <el-form-item label="文案类目 / 关键词"><el-input v-model="pipeline.category_hint" placeholder="类目提示"/><el-input v-model="pipeline.page_keywords" placeholder="关键词，逗号分隔"/></el-form-item>
          <el-form-item label="水印文件 / 位置"><el-input v-model="pipeline.watermark_filename"/><el-select v-model="pipeline.watermark_position"><el-option label="右下" value="bottom-right"/><el-option label="左下" value="bottom-left"/><el-option label="右上" value="top-right"/><el-option label="左上" value="top-left"/><el-option label="居中" value="center"/></el-select></el-form-item>
          <el-form-item label="大小 / 透明度"><el-input-number v-model="pipeline.watermark_scale" :min="0.05" :max="1" :step="0.05"/><el-input-number v-model="pipeline.watermark_opacity" :min="0.05" :max="1" :step="0.05"/></el-form-item>
        </el-form></div>
        <div><h3 class="config-title">4. OSS 与接口配置</h3><el-form label-width="125px" class="pipeline-form">
          <el-form-item label="OSS 存储目录"><el-input v-model="pipeline.original_oss_prefix" placeholder="原图目录"/><el-input v-model="pipeline.watermarked_oss_prefix" placeholder="水印图目录"/></el-form-item>
          <el-form-item label="AI 接口"><el-select v-model="pipeline.ai_chat_connection_id" placeholder="文案/分析模型"><el-option v-for="x in connections.filter(x=>x.provider==='ai_chat')" :key="x.id" :label="x.name" :value="x.id"/></el-select><el-select v-model="pipeline.ai_image_connection_id" placeholder="生图模型"><el-option v-for="x in connections.filter(x=>x.provider==='ai_image')" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item>
          <el-form-item label="OSS 接口"><el-select v-model="pipeline.oss_connection_id" placeholder="OSS 连接"><el-option v-for="x in connections.filter(x=>x.provider==='oss')" :key="x.id" :label="x.name" :value="x.id"/></el-select><el-switch v-model="pipeline.oss_dry_run"/><span class="form-tip">测试模式不真实上传</span></el-form-item>
        </el-form></div>
        <div class="pipeline-runbar"><span>已选择 <b>{{pipeline.selected_steps.length}}</b> 个步骤</span><div class="pipeline-actions"><el-button size="large" :loading="pipelineLoading" @click="startPipeline(true)">只补跑失败/缺失图片</el-button><el-button size="large" type="primary" :disabled="!pipeline.selected_steps.length" :loading="pipelineLoading" @click="startPipeline(false)"><Play :size="17"/>运行选中步骤</el-button></div></div>
      </div>
    </section>
    <section class="self-grid">
      <div class="panel upload-panel"><div class="panel-head"><div><h2>回传处理结果</h2><p>选择本地程序最终输出的 Excel</p></div></div><div class="panel-body">
        <label class="result-picker" :class="{selected:file}"><FileSpreadsheet :size="34"/><b>{{file?.name||'选择自主上架结果表'}}</b><span>{{file?'文件已选择，可以先校验':'支持 .xlsx 和 .xlsm'}}</span><input type="file" accept=".xlsx,.xlsm" @change="file=($event.target as HTMLInputElement).files?.[0]"/></label>
        <div class="category-picker"><div class="category-row"><el-select v-model="categoryStoreId" placeholder="选择 Ozon 店铺" @change="loadCategoryOptions"><el-option v-for="store in ozonStores" :key="store.id" :label="store.name" :value="store.id"/></el-select><el-button :loading="categoryLoading" @click="syncCategories">同步 Ozon 类目树</el-button></div><el-select-v2 v-model="selectedCategoryKey" :options="categorySelectOptions" filterable clearable :loading="categoryLoading" :height="280" placeholder="搜索并选择本批产品的 Ozon 类目" style="width:100%" /><small v-if="categoryMeta">本地快照：{{categoryMeta.option_count}} 个类目 · {{new Date(categoryMeta.synced_at).toLocaleString()}}</small><small v-else>请先同步一次类目树；之后可直接使用本地快照。</small></div>
        <el-alert title="建议先执行“只校验”。校验不会写入产品库。" type="info" :closable="false" show-icon/>
        <div class="primary-actions"><el-button size="large" :disabled="!file" :loading="loading" @click="upload(true)">只校验</el-button><el-button size="large" type="primary" :disabled="!file" :loading="loading" @click="upload(false)"><UploadCloud :size="17"/>校验并入库</el-button></div>
      </div></div>
      <div class="panel rules-panel"><div class="panel-head"><div><h2>ERP 实际读取字段</h2><p>标准模板中的其他列不会入库</p></div><el-tag type="success" effect="plain">{{ inputFields.length + generatedFields.length }} 个字段</el-tag></div><div class="panel-body">
        <h3>使用者填写</h3><div class="field-cloud"><span v-for="field in inputFields" :key="field">{{field}}</span></div>
        <h3>本地程序回填</h3><div class="field-cloud generated"><span v-for="field in generatedFields" :key="field">{{field}}</span></div>
        <div class="compatibility"><CheckCircle2 :size="18"/><div><b>允许调整表格结构</b><span>列顺序不限；表头可在第 2 行，也可删除分组行后放到第 1 行；“商品名称”和“产品名称”都能识别。</span></div></div>
      </div></div>
    </section>
    <el-collapse class="backup-import"><el-collapse-item title="备用：导入含本地图片的 ZIP 资料包" name="bundle"><div class="backup-row"><label class="file-picker"><input type="file" accept=".zip,application/zip" @change="bundleFile=($event.target as HTMLInputElement).files?.[0]"/><span>{{bundleFile?.name||'选择 ZIP 产品资料包'}}</span></label><el-button :loading="bundleLoading" @click="uploadBundle(true)">只校验</el-button><el-button :loading="bundleLoading" @click="uploadBundle(false)">导入资料包</el-button></div></el-collapse-item></el-collapse>
    <el-alert v-if="pipelineJob" type="success" :closable="false"><template #title>流水线任务已创建，<RouterLink :to="`/jobs?job=${pipelineJob.id}`">查看任务进度</RouterLink></template></el-alert>
  </template>
  <section v-else class="split-grid">
    <div v-if="mode!=='self_selected'" class="panel"><div class="panel-head"><div><h2>POD 历史产品</h2><p>原地读取“指纹科技图片合成”，不搬移、不修改原文件</p></div></div><div class="panel-body import-guide"><p>迁移产品主档、颜色尺码 SKU、供应商生产编码、当前配方、效果图和 OSS 资产。任务可以重复执行，使用旧系统 ID 防止重复。</p><el-alert title="建议先预演核对数量，再执行全量索引。迁移过程不调用 AI，也不会调用生产下单接口。" type="info" :closable="false"/><div class="import-actions"><el-button :loading="podLoading==='dry'" @click="pod(true)">预演并校验</el-button><el-button type="primary" :loading="podLoading==='run'" @click="pod(false)">执行全量迁移</el-button></div></div></div>
  </section>
  <section class="panel"><div class="panel-head"><div><h2>{{mode==='self_selected'?'回传记录':'导入记录'}}</h2><p>预演与正式入库均保留校验结果</p></div><el-button @click="load">刷新</el-button></div><el-table :data="visibleItems" empty-text="还没有回传记录"><el-table-column label="文件类型" width="150"><template #default="s">{{s.row.kind==='pod_history'?'POD 历史':s.row.kind==='self_selected_bundle'?'ZIP 资料包':'标准模板'}}</template></el-table-column><el-table-column label="执行方式" width="105"><template #default="s"><el-tag :type="s.row.dry_run?'info':'primary'">{{s.row.dry_run?'只校验':'正式入库'}}</el-tag></template></el-table-column><el-table-column label="状态" width="130"><template #default="s"><el-tag :type="statusType(s.row.status)">{{statusText(s.row.status)}}</el-tag></template></el-table-column><el-table-column label="统计" min-width="300"><template #default="s">{{values(s.row.counts)}}</template></el-table-column><el-table-column label="问题" min-width="220"><template #default="s"><span :class="{'danger-copy':s.row.errors?.length}">{{s.row.errors?.length?`${s.row.errors.length} 项需要处理`:'无'}}</span></template></el-table-column><el-table-column label="操作" width="110"><template #default="s"><RouterLink v-if="s.row.job_id" :to="`/jobs?job=${s.row.job_id}`">查看详情</RouterLink></template></el-table-column></el-table></section>
  <el-dialog v-model="pipelineOpen" title="选择自主上架处理步骤" width="780px"><div class="step-heading"><span>可以只运行任意一步，也可按选中顺序运行全部流程。</span><el-button link type="primary" @click="selectAllSteps">全选</el-button></div><el-checkbox-group v-model="pipeline.selected_steps" class="step-picker"><el-checkbox v-for="step in stepOptions" :key="step[0]" :value="step[0]" border><b>{{step[1]}}</b><small>{{step[2]}}</small></el-checkbox></el-checkbox-group><el-form label-width="145px" class="pipeline-form"><el-form-item label="产品图片根目录"><el-input v-model="pipeline.product_root" placeholder="例如 D:\产品批次\图片"/></el-form-item><el-form-item label="输出表格目录"><el-input v-model="pipeline.output_dir" placeholder="留空自动创建"/></el-form-item><el-form-item v-if="pipeline.selected_steps.includes('watermark')||pipeline.selected_steps.includes('upload_watermarked')" label="水印图目录"><el-input v-model="pipeline.watermark_root" placeholder="留空自动创建"/></el-form-item><el-form-item v-if="pipeline.selected_steps.includes('watermark')" label="水印文件名 / 位置"><el-input v-model="pipeline.watermark_filename"/><el-select v-model="pipeline.watermark_position" style="width:160px"><el-option label="右下" value="bottom-right"/><el-option label="左下" value="bottom-left"/><el-option label="右上" value="top-right"/><el-option label="左上" value="top-left"/><el-option label="居中" value="center"/></el-select></el-form-item><el-form-item v-if="pipeline.selected_steps.includes('watermark')" label="水印大小 / 透明度"><el-input-number v-model="pipeline.watermark_scale" :min="0.05" :max="1" :step="0.05"/><el-input-number v-model="pipeline.watermark_opacity" :min="0.05" :max="1" :step="0.05"/></el-form-item><el-form-item v-if="pipeline.selected_steps.includes('generate_images')" label="每产品生成图片"><el-input-number v-model="pipeline.image_plan_count" :min="1" :max="12"/><el-input v-model="pipeline.product_hint" placeholder="产品提示，可留空"/></el-form-item><el-form-item v-if="pipeline.selected_steps.includes('generate_copywriting')" label="文案类目 / 关键词"><el-input v-model="pipeline.category_hint"/><el-input v-model="pipeline.page_keywords" placeholder="关键词，逗号分隔"/></el-form-item><el-form-item v-if="pipeline.selected_steps.includes('upload_original')" label="原图 OSS 目录"><el-input v-model="pipeline.original_oss_prefix"/></el-form-item><el-form-item v-if="pipeline.selected_steps.includes('upload_watermarked')" label="水印图 OSS 目录"><el-input v-model="pipeline.watermarked_oss_prefix"/></el-form-item><el-form-item v-if="pipeline.selected_steps.some((x:string)=>['generate_images','generate_copywriting'].includes(x))" label="AI 接口"><el-select v-model="pipeline.ai_chat_connection_id" placeholder="AI 文案/分析"><el-option v-for="x in connections.filter(x=>x.provider==='ai_chat')" :key="x.id" :label="x.name" :value="x.id"/></el-select><el-select v-if="pipeline.selected_steps.includes('generate_images')" v-model="pipeline.ai_image_connection_id" placeholder="AI 图片"><el-option v-for="x in connections.filter(x=>x.provider==='ai_image')" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item v-if="pipeline.selected_steps.some((x:string)=>x.startsWith('upload_'))" label="OSS 接口 / 测试"><el-select v-model="pipeline.oss_connection_id" placeholder="OSS"><el-option v-for="x in connections.filter(x=>x.provider==='oss')" :key="x.id" :label="x.name" :value="x.id"/></el-select><el-switch v-model="pipeline.oss_dry_run"/><span class="form-tip">测试模式不真实上传</span></el-form-item></el-form><template #footer><el-button @click="pipelineOpen=false">取消</el-button><el-button type="primary" :disabled="!pipeline.selected_steps.length" :loading="pipelineLoading" @click="startPipeline(false)">运行选中的 {{pipeline.selected_steps.length}} 个步骤</el-button></template></el-dialog>
</div></template>

